import{surfaceColor,perspective,solidStage,smoothSphere}from'./material.js';
import{Base,fmt,svgEl}from'./base.js';import{clamp,solidMetrics}from'../math.js';
export default class Solid extends Base{
 constructor(host,ctx){super(host,ctx);this.rx=.35;this.ry=.6;this.zoom=1;this.playing=false;this.speed=1;this.scale=24;this.select('shape',{label:'Solid | ठोस',items:[['cuboid','Cuboid','घनाभ'],['cylinder','Cylinder','बेलन'],['cone','Cone','शंकु'],['sphere','Sphere','गोला']]},ctx.scene.id||'cuboid');this.dims=[this.slider('x','Length / radius','लंबाई / त्रिज्या',1,8,3,.25,'cm'),this.slider('y','Breadth / height','चौड़ाई / ऊँचाई',1,8,4,.25,'cm'),this.slider('z','Height (cuboid only)','ऊँचाई (केवल घनाभ)',1,8,5,.25,'cm')];this.listen(this.svg,'pointerdown',e=>{this.rot=[e.clientX,e.clientY];this.svg.setPointerCapture(e.pointerId)});this.listen(this.svg,'pointermove',e=>{if(!this.rot)return;this.ry+=(e.clientX-this.rot[0])*.012;this.rx+=(e.clientY-this.rot[1])*.012;this.rot=[e.clientX,e.clientY];this.changed=true;this.draw();ctx.onChange?.()});this.listen(this.svg,'pointerup',()=>this.rot=null);this.listen(this.svg,'pointercancel',()=>this.rot=null);this.listen(this.svg,'wheel',e=>{e.preventDefault();this.zoom=clamp(this.zoom-e.deltaY*.001,.4,2);this.draw()},{passive:false});this.listen(this.svg,'keydown',e=>{let map={ArrowLeft:[0,-.1],ArrowRight:[0,.1],ArrowUp:[-.1,0],ArrowDown:[.1,0]};if(map[e.key]){e.preventDefault();this.rx+=map[e.key][0];this.ry+=map[e.key][1];this.draw()}if(e.key==='+'||e.key==='-'){this.zoom=clamp(this.zoom+(e.key==='+'?.1:-.1),.4,2);this.draw()}});this.update();this.draw();this.listen(document,'visibilitychange',()=>{this.last=0;if(!document.hidden&&this.playing)this.animate()})}
 update(){if(!this.dims)return;this.dims[1].hidden=this.shape==='sphere';this.dims[2].hidden=this.shape!=='cuboid'}
 rotate(p){let[x,y,z]=p,a=x*Math.cos(this.ry)+z*Math.sin(this.ry),c=-x*Math.sin(this.ry)+z*Math.cos(this.ry);return[a,y*Math.cos(this.rx)-c*Math.sin(this.rx),y*Math.sin(this.rx)+c*Math.cos(this.rx)]}
 draw(){this.clear(false);solidStage(this.svg);let faces=[],x=this.x||3,y=this.y||4,z=this.z||5,s=this.shape||'cuboid',n=this.ctx.lowpower?16:32,add=p=>faces.push(p);
 if(s==='cuboid'){let v=[[-x/2,-z/2,-y/2],[x/2,-z/2,-y/2],[x/2,z/2,-y/2],[-x/2,z/2,-y/2],[-x/2,-z/2,y/2],[x/2,-z/2,y/2],[x/2,z/2,y/2],[-x/2,z/2,y/2]];for(let f of [[0,1,2,3],[4,7,6,5],[0,4,5,1],[3,2,6,7],[0,3,7,4],[1,5,6,2]])add(f.map(i=>v[i]))}
 else if(s==='sphere'){for(let j=0;j<n/2;j++)for(let i=0;i<n;i++){let p=[];for(let[u,v]of [[i,j],[i+1,j],[i+1,j+1],[i,j+1]]){let a=u*2*Math.PI/n,b=-Math.PI/2+v*2*Math.PI/n;p.push([x*Math.cos(b)*Math.cos(a),x*Math.sin(b),x*Math.cos(b)*Math.sin(a)])}add(p)}}
 else{let bottom=[],top=[];for(let i=0;i<n;i++){let a=i*2*Math.PI/n,b=(i+1)*2*Math.PI/n,p=[x*Math.cos(a),-y/2,x*Math.sin(a)],q=[x*Math.cos(b),-y/2,x*Math.sin(b)],r=[q[0],y/2,q[2]],u=[p[0],y/2,p[2]];bottom.push(p);top.push(u);add(s==='cone'?[p,q,[0,y/2,0]]:[p,q,r,u])}add(bottom);if(s==='cylinder')add(top)}
 let transformed=faces.map(p=>p.map(v=>this.rotate(v)));transformed.sort((a,b)=>a.reduce((s,v)=>s+v[2],0)/a.length-b.reduce((s,v)=>s+v[2],0)/b.length);let fit=Math.min(1,7/Math.max(x,y,s==='cuboid'?z:2*x)),sc=29*this.zoom*fit;if(s==='sphere')smoothSphere(this.svg,x*sc*32/Math.sqrt(32**2-x**2));else for(let p of transformed){let u=p[1].map((v,i)=>v-p[0][i]),v=p[2].map((q,i)=>q-p[0][i]),normal=[u[1]*v[2]-u[2]*v[1],u[2]*v[0]-u[0]*v[2],u[0]*v[1]-u[1]*v[0]],len=Math.hypot(...normal)||1,outward=p.reduce((s,v)=>s+v[0]*normal[0]+v[1]*normal[1]+v[2]*normal[2],0)>=0?1:-1,light=Math.max(0,outward*(normal[0]*.5+normal[1]*1+normal[2]*.3)/len/Math.sqrt(1.34)),bright=.4+.6*light;let points=p.map(v=>perspective(v,sc).slice(0,2).join(',')).join(' ');this.svg.append(svgEl('polygon',{points,fill:surfaceColor(p),stroke:s==='cuboid'?'#163f3570':'none','stroke-width':.5}))}if(this.labels){this.svg.append(svgEl('text',{x:20,y:30},this.ctx.t({cuboid:'Cuboid',cylinder:'Cylinder',cone:'Cone',sphere:'Sphere'}[s],{cuboid:'घनाभ',cylinder:'बेलन',cone:'शंकु',sphere:'गोला'}[s])));this.svg.append(svgEl('text',{x:20,y:370},s==='cuboid'?`l = ${x} cm · b = ${y} cm · h = ${z} cm`:`r = ${x} cm`+(s==='sphere'?'':` · h = ${y} cm`)))}let m=solidMetrics(s,x,y,z);this.output(`${m.formula}\n${this.ctx.t('Total surface area','संपूर्ण पृष्ठीय क्षेत्रफल')} ≈ ${fmt(m.tsa)} cm²\n${m.vformula}\n${this.ctx.t('Volume','आयतन')} ≈ ${fmt(m.volume)} cm³\nπ = ${fmt(Math.PI)}…`)}
 animate(){if(this.frame)return;let run=time=>{this.frame=null;if(!this.playing||document.hidden)return;let dt=Math.min(.05,(time-(this.last||time))/1000);this.last=time;this.ry+=dt*.4*(this.speed||1);if(!this.ctx.lowpower||!this.lastDraw||time-this.lastDraw>32){this.draw();this.lastDraw=time}this.frame=requestAnimationFrame(run)};this.frame=requestAnimationFrame(run)}
 pause(){this.playing=!this.playing;this.animate();return this.playing}
 resetView(){this.rx=.35;this.ry=.6;this.zoom=1;this.draw()}
 destroy(){cancelAnimationFrame(this.frame);super.destroy()}
}
